inline const float* heavy_hex_3x3_ideal_kick_eps010_ptm(int bond_id, float gamma) {
    int best = 0;
    float best_diff = fabsf(gamma - HEAVY_HEX_3x3_DEP_IDEAL_KICK_EPS010_GAMMAS[0]);
    for (int i = 1; i < HEAVY_HEX_3x3_DEP_IDEAL_KICK_EPS010_N_GAMMA; i++) {
        float diff = fabsf(gamma - HEAVY_HEX_3x3_DEP_IDEAL_KICK_EPS010_GAMMAS[i]);
        if (diff < best_diff) { best = i; best_diff = diff; }
    }
    if (best == 0) return HEAVY_HEX_3x3_DEP_IDEAL_KICK_EPS010_GAMMA1_0[bond_id];
    if (best == 1) return HEAVY_HEX_3x3_DEP_IDEAL_KICK_EPS010_GAMMA2_0[bond_id];
    return HEAVY_HEX_3x3_DEP_IDEAL_KICK_EPS010_GAMMA3_0[bond_id];
}
